def flood(g):
    H,W=len(g),len(g[0]); seen=set(); q=deque()
    for i in range(H):
        for j in (0,W-1):
            if g[i][j]==0 and (i,j) not in seen: seen.add((i,j)); q.append((i,j))
    for j in range(W):
        for i in (0,H-1):
            if g[i][j]==0 and (i,j) not in seen: seen.add((i,j)); q.append((i,j))
    while q:
        a,b=q.popleft()
        for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
            n=(a+di,b+dj)
            if 0<=n[0]<H and 0<=n[1]<W and g[n[0]][n[1]]==0 and n not in seen:
                seen.add(n); q.append(n)
    return seen
def enc_comps(g):
    seen=flood(g); comps=[]
    for i in range(len(g)):
        for j in range(len(g[0])):
            if g[i][j]==0 and (i,j) not in seen:
                st=[(i,j)]; comp=[]; seen.add((i,j))
                while st:
                    a,b=st.pop(); comp.append((a,b))
                    for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
                        mm=(a+di,b+dj)
                        if 0<=mm[0]<len(g) and 0<=mm[1]<len(g[0]) and g[mm[0]][mm[1]]==0 and mm not in seen:
                            seen.add(mm); st.append(mm)
                rs=[a for a,b in comp]; cs=[b for a,b in comp]
                R0,R1,C0,C1=min(rs),max(rs),min(cs),max(cs)
                comps.append(((R0,R1,C0,C1),comp))
    return comps
